import math,json
out={}
for n in (1,3,128,129,512,513):
 blocks=(n+511)//512
 written=[i for t in range(blocks*256) if t<n//2 for i in (2*t,2*t+1)]
 out[n]={'blocks':blocks,'written':len(written),'missing':sorted(set(range(n))-set(written))}
print(json.dumps({'coverage':out,'sqrt_2_over_pi':math.sqrt(2/math.pi),'literal_error':0.797884560803-math.sqrt(2/math.pi)}))
